/**
 * Pure cookie helpers shared by the popup and the unit tests.
 * No browser APIs are used here, so this module runs in Node too.
 */

const HEADER = [
  "# Netscape HTTP Cookie File",
  "# Generated by YouTube Cookies Exporter (Crazy Downloader)",
  "# https://github.com/nayandas69/crazy-downloader/tree/main/extension",
].join("\n");

/** Cookie names that only exist on a signed-in YouTube session. */
export const SESSION_COOKIE_NAMES = [
  "LOGIN_INFO",
  "SID",
  "HSID",
  "SSID",
  "APISID",
  "SAPISID",
  "__Secure-1PSID",
  "__Secure-3PSID",
];

function stripControlChars(value) {
  return String(value ?? "").replace(/[\t\r\n]/g, "");
}

/** True when the cookie belongs to youtube.com or one of its subdomains. */
export function isYouTubeCookie(cookie) {
  const domain = stripControlChars(cookie?.domain).replace(/^\./, "").toLowerCase();
  return domain === "youtube.com" || domain.endsWith(".youtube.com");
}

/**
 * Convert `chrome.cookies.Cookie` objects into Netscape cookies.txt lines.
 * HttpOnly cookies are prefixed with `#HttpOnly_`, which is how a cookie jar
 * (yt-dlp included) tells them apart from comments.
 */
export function cookiesToLines(cookies) {
  const lines = [];
  const seen = new Set();

  for (const cookie of cookies ?? []) {
    if (!isYouTubeCookie(cookie)) continue;

    const name = stripControlChars(cookie.name);
    if (!name) continue;

    const bareDomain = stripControlChars(cookie.domain).replace(/^\./, "").toLowerCase();
    // hostOnly cookies must not be sent to subdomains, so they keep a bare domain.
    const domain = cookie.hostOnly ? bareDomain : `.${bareDomain}`;
    const includeSubdomains = cookie.hostOnly ? "FALSE" : "TRUE";
    const path = stripControlChars(cookie.path).startsWith("/") ? stripControlChars(cookie.path) : "/";
    const key = `${domain}\t${path}\t${name}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const secure = cookie.secure ? "TRUE" : "FALSE";
    const expires =
      typeof cookie.expirationDate === "number" && Number.isFinite(cookie.expirationDate)
        ? Math.floor(cookie.expirationDate)
        : 0;
    const value = stripControlChars(cookie.value);
    const prefix = cookie.httpOnly ? "#HttpOnly_" : "";

    lines.push(
      `${prefix}${domain}\t${includeSubdomains}\t${path}\t${secure}\t${expires}\t${name}\t${value}`
    );
  }

  lines.sort((a, b) => a.replace(/^#HttpOnly_/, "").localeCompare(b.replace(/^#HttpOnly_/, "")));
  return lines;
}

/** Full cookies.txt text, ready to paste into Crazy Downloader's cookie settings. */
export function buildCookiesTxt(cookies) {
  const lines = cookiesToLines(cookies);
  return lines.length === 0 ? `${HEADER}\n` : `${HEADER}\n\n${lines.join("\n")}\n`;
}

/** Counts the exported cookies and whether the session looks signed in. */
export function summarizeCookies(cookies) {
  const youtubeCookies = (cookies ?? []).filter(isYouTubeCookie);
  const names = new Set(youtubeCookies.map((c) => stripControlChars(c.name)));
  const signedIn = SESSION_COOKIE_NAMES.some((name) => names.has(name));
  return { total: youtubeCookies.length, signedIn };
}
